from django.conf import settings
from rest_framework import viewsets, permissions, status
from rest_framework.decorators import action
from rest_framework.response import Response
from django.db.models import Q
from app.documents.models import DocumentRequest, Evidence, Folder
from .serializers import DocumentRequestSerializer, EvidenceSerializer, PresignedUrlSerializer, FolderSerializer
from app.common.services.storage_service import StorageService
from app.tenants.permissions import has_client_view_all, scope_by_client
import uuid

class DocumentRequestViewSet(viewsets.ModelViewSet):
    serializer_class = DocumentRequestSerializer
    permission_classes = [permissions.IsAuthenticated]

    def get_queryset(self):
        # Prefetch items + their uploaded evidence so the nested item `files` field isn't a
        # query per item (introduced with #315; fixed in the #316 sweep).
        queryset = DocumentRequest.objects.select_related(
            'process_step', 'created_by',
        ).prefetch_related('items', 'items__evidence_set')
        client_id = self.request.query_params.get('client')
        if client_id:
            queryset = queryset.filter(client_id=client_id)
        process_run = self.request.query_params.get('process_run')
        if process_run:
            queryset = queryset.filter(process_run_id=process_run)
        process_step = self.request.query_params.get('process_step')
        if process_step:
            queryset = queryset.filter(process_step_id=process_step)
        return scope_by_client(queryset, self.request.user, 'client')

    def perform_create(self, serializer):
        serializer.save(created_by=self.request.user)

    @action(detail=True, methods=['post'], url_path='portal-link')
    def portal_link(self, request, pk=None):
        """Mint (or reuse) a client-portal access token for this request and return the
        shareable link (#312). Firm-authenticated; the client uses the link with no login.
        Reuses a still-live token so re-sharing doesn't churn tokens."""
        from app.documents.models import DocumentRequestAccessToken

        doc_request = self.get_object()
        # issue() revokes any prior live token and mints a fresh one (single active link).
        token, raw = DocumentRequestAccessToken.issue(doc_request, created_by=request.user)
        return Response(
            {'token': raw, 'path': f'/portal/{raw}', 'expires_at': token.expires_at},
            status=status.HTTP_201_CREATED,
        )

    @action(detail=True, methods=['post'], url_path='revoke-portal-link')
    def revoke_portal_link(self, request, pk=None):
        """Revoke every live client-portal token for this request (#315) — kills any
        shared link so the client can no longer open the portal."""
        from django.utils import timezone
        doc_request = self.get_object()
        now = timezone.now()
        revoked = 0
        for tok in doc_request.access_tokens.filter(revoked_at__isnull=True, expires_at__gt=now):
            tok.revoked_at = now
            tok.save(update_fields=['revoked_at'])
            revoked += 1
        return Response({'revoked': revoked}, status=status.HTTP_200_OK)

class FolderViewSet(viewsets.ModelViewSet):
    serializer_class = FolderSerializer
    permission_classes = [permissions.IsAuthenticated]

    def get_queryset(self):
        queryset = Folder.objects.all()
        client_id = self.request.query_params.get('client')
        if client_id:
            queryset = queryset.filter(client_id=client_id)
        process_run = self.request.query_params.get('process_run')
        if process_run:
            queryset = queryset.filter(process_run_id=process_run)
        parent = self.request.query_params.get('parent')
        if parent:
            queryset = queryset.filter(parent_id=parent)
        task = self.request.query_params.get('task')
        if task:
            queryset = queryset.filter(task_id=task)
        if not has_client_view_all(self.request.user):
            queryset = queryset.filter(
                Q(client__assigned_team=self.request.user)
                | Q(process_run__client__assigned_team=self.request.user)
                | Q(task__account__assigned_team=self.request.user)
            ).distinct()
        return queryset

    def perform_create(self, serializer):
        serializer.save()

class EvidenceViewSet(viewsets.ModelViewSet):
    serializer_class = EvidenceSerializer
    permission_classes = [permissions.IsAuthenticated]

    def get_queryset(self):
        queryset = Evidence.objects.all()

        folder = self.request.query_params.get('folder')
        if folder:
            queryset = queryset.filter(folder_id=folder)

        step = self.request.query_params.get('step')
        if step:
            queryset = queryset.filter(process_step_id=step)

        run = self.request.query_params.get('run')
        if run:
            queryset = queryset.filter(process_run_id=run)

        # Evidence has no direct client FK — scope via its folder or process run.
        client_id = self.request.query_params.get('client')
        if client_id:
            queryset = queryset.filter(
                Q(folder__client_id=client_id) | Q(process_run__client_id=client_id)
            )

        if not has_client_view_all(self.request.user):
            queryset = queryset.filter(
                Q(process_run__client__assigned_team=self.request.user)
                | Q(process_step__process_run__client__assigned_team=self.request.user)
                | Q(folder__client__assigned_team=self.request.user)
                | Q(folder__task__account__assigned_team=self.request.user)
                | Q(document_request_item__document_request__client__assigned_team=self.request.user)
            ).distinct()

        return queryset.distinct()

    def perform_create(self, serializer):
        serializer.save(uploaded_by=self.request.user)

    @action(detail=False, methods=['post'])
    def upload(self, request):
        """
        Server-side file upload for the folder document browser: the browser POSTs a
        multipart file (+ optional folder), Django streams it to S3/MinIO and records
        the Evidence row. Avoids a browser->storage CORS hop for the documents view.
        """
        upload = request.FILES.get('file')
        if not upload:
            return Response({'error': 'No file provided'}, status=status.HTTP_400_BAD_REQUEST)

        max_bytes = getattr(settings, 'MAX_EVIDENCE_UPLOAD_BYTES', 52428800)
        if upload.size > max_bytes:
            return Response(
                {'error': f'File exceeds the {max_bytes} byte limit'},
                status=status.HTTP_413_REQUEST_ENTITY_TOO_LARGE,
            )

        from django.db import connection
        content_type = upload.content_type or 'application/octet-stream'
        file_key = f"evidence/{connection.tenant.id}/{uuid.uuid4()}/{upload.name}"

        if not StorageService.upload_fileobj(upload.file, file_key, content_type):
            return Response(
                {'error': 'Could not store file'},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR,
            )

        folder = request.data.get('folder') or None
        process_run = request.data.get('process_run') or None
        process_step = request.data.get('process_step') or None
        evidence = Evidence.objects.create(
            type='FILE',
            folder_id=folder,
            process_run_id=process_run,
            process_step_id=process_step,
            file_key=file_key,
            filename=upload.name,
            content_type=content_type,
            size=upload.size,
            uploaded_by=request.user,
        )
        return Response(
            self.get_serializer(evidence).data,
            status=status.HTTP_201_CREATED,
        )

    @action(detail=False, methods=['post'])
    def presigned_upload(self, request):
        """
        Generate a presigned upload URL for S3.
        """
        serializer = PresignedUrlSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)

        # Security: Prefix key with tenant_id to enforce isolation
        raw_key = serializer.validated_data['key']
        from django.db import connection
        file_key = f"evidence/{connection.tenant.id}/{raw_key}"
        content_type = serializer.validated_data.get('content_type', 'application/octet-stream')

        data = StorageService.generate_presigned_upload(file_key, content_type)
        if not data:
             return Response({'error': 'Could not generate URL'}, status=status.HTTP_500_INTERNAL_SERVER_ERROR)

        return Response(data)

    @action(detail=True, methods=['get'])
    def presigned_download(self, request, pk=None):
        evidence = self.get_object()
        if not evidence.file_key:
            return Response({'error': 'No file key'}, status=status.HTTP_404_NOT_FOUND)

        url = StorageService.generate_presigned_download(evidence.file_key)
        if not url:
            return Response({'error': 'Could not generate URL'}, status=status.HTTP_500_INTERNAL_SERVER_ERROR)

        return Response({'url': url})

